// Builds every generated file of the suite repo as path → content (§8 M6). Pure: no I/O, deterministic output.
import { createHash } from 'node:crypto';
import type { RoleMatrix } from '../authz/matrix-io.js';
import { SATISFIES } from '../authz/propose.js';
import type { AppConfig, LedgerEvent } from '../core/schemas.js';
import type { Candidate, FormInfo, TextElement } from '../crawler/candidates.js';
import type { LocatorDescriptor } from '../crawler/locator.js';
import type { AssertionT } from '../dsl/validate.js';
import type { AuthScheme } from '../onboarding/auth-material.js';
import type { Binding } from '../spec/domain-pack.js';
import type { Entity } from '../spec/entities.js';
import type { ApiModel } from '../spec/har-to-openapi.js';
import type { RuleT } from '../spec/rule-proposer.js';
import { CompileError, emitAssertion } from './dsl-to-ts.js';
import { camel, methodName, pageClassName, slug, testName, uniqueNames } from './names.js';
import { FAULTS_TS } from './static-faults.js';
import * as S from './static-files.js';

export const PRAMAAN_VERSION = '0.1.0';
const MIRRORED = new Set(['rule.decided', 'matrix.decided', 'assertion.decided', 'finding.verdict', 'lead.session', 'test.quarantined', 'test.promoted', 'test.demoted', 'bench.result', 'mutation.result', 'run.completed']);

export interface CrawlState {
  role: string;
  route: string;
  url: string;
  candidates: Candidate[];
  forms: FormInfo[];
  texts: TextElement[];
}

export interface CompileInputs {
  config: AppConfig;
  model: ApiModel;
  entities: Entity[];
  bindings: Binding[];
  matrix: RoleMatrix;
  rules: RuleT[];
  assertions: AssertionT[];
  states: CrawlState[];
  authScheme: AuthScheme | undefined;
  teardownOps: Map<string, { op: string; actor?: string | undefined }>;
  ledgerEvents: LedgerEvent[];
  specTexts: Record<string, string>; // spec/<name> → raw text (openapi.observed.yaml, entities.yaml, rules.yaml, role-matrix.yaml)
  jsonpathSource: string; // Pramaan's self-contained JSONPath subset, copied into helpers/
}

export interface TestIndexEntry {
  file: string;
  title: string;
  tags: string[];
  oracle: 'confirmed-rule' | 'authz-matrix' | 'consistency' | 'implicit';
  operations: string[];
  /** JSONPaths read per operation; '$' = the whole body, '#status' = only the status code. */
  reads: Record<string, string[]>;
  ruleIds: string[];
  assertionIds: string[];
}

export interface Generated {
  files: Map<string, string>;
  index: TestIndexEntry[];
  skipped: { what: string; reason: string }[];
}

const sha8 = (s: string): string => createHash('sha1').update(s).digest('hex').slice(0, 8);
/** TS files carry the generated-by header; its hash is of the body, so regeneration is byte-stable. */
const ts = (body: string): string => `// generated by pramaan ${PRAMAAN_VERSION} from ${sha8(body)} — edit via spec/ or regenerate\n${body}`;
const q = (s: string): string => JSON.stringify(s);

function locatorCode(d: LocatorDescriptor): string {
  switch (d.strategy) {
    case 'testid':
      return `this.page.getByTestId(${q(d.value)})`;
    case 'role':
      return `this.page.getByRole(${q(d.value)}${d.name !== undefined ? `, { name: ${q(d.name)}, exact: true }` : ''})`;
    case 'label':
      return `this.page.getByLabel(${q(d.value)}, { exact: true })`;
    case 'placeholder':
      return `this.page.getByPlaceholder(${q(d.value)}, { exact: true })`;
    case 'css-id':
      return `this.page.locator(${q(`#${d.value}`)})`;
  }
}

interface PageInfo {
  route: string;
  className: string;
  file: string;
  openPath: string; // path with {id} → param
  getters: Map<string, string>; // candidate key or text testid → getter name
}

const ROLE_SUFFIX: Record<string, string> = { link: 'Link', button: 'Button', tab: 'Tab', menuitem: 'MenuItem', generic: 'Element' };

function buildPages(states: CrawlState[], loginPath: string): { files: Map<string, string>; pages: Map<string, PageInfo> } {
  const files = new Map<string, string>();
  const pages = new Map<string, PageInfo>();
  const byRoute = new Map<string, CrawlState[]>();
  for (const s of states) {
    if (s.route === loginPath) continue;
    byRoute.set(s.route, [...(byRoute.get(s.route) ?? []), s]);
  }
  for (const [route, ss] of [...byRoute.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    const className = pageClassName(route);
    const first = ss[0];
    if (!first) continue;
    const u = new URL(first.url);
    const openPath = route.includes('{id}') ? route.split('?')[0] ?? route : `${u.pathname}${u.search}`;
    const lines: string[] = [];
    const getters = new Map<string, string>();
    const used = new Set<string>(['open']);
    const name = (base: string): string => {
      let n = base;
      for (let i = 2; used.has(n); i++) n = `${base}${i}`;
      used.add(n);
      return n;
    };
    for (const c of ss.flatMap((s) => s.candidates)) {
      if (c.descriptor.scope || getters.has(c.key)) continue;
      const label = c.name.length > 0 && c.name.length <= 40 ? c.name : (c.testid ?? '');
      if (!label) continue;
      const getter = name(`${camel(label)}${ROLE_SUFFIX[c.role] ?? 'Element'}`);
      getters.set(c.key, getter);
      lines.push(`  ${getter}(): Locator {`, `    return ${locatorCode(c.descriptor)};`, '  }', '');
      lines.push(`  async ${name(methodName('click', label))}(): Promise<void> {`, `    await this.${getter}().click();`, '  }', '');
    }
    for (const f of ss.flatMap((s) => s.forms).flatMap((x) => x.fields)) {
      if (!f.descriptor || !f.label || getters.has(`field:${f.label}`)) continue;
      const getter = name(`${camel(f.label)}Field`);
      getters.set(`field:${f.label}`, getter);
      lines.push(`  ${getter}(): Locator {`, `    return ${locatorCode(f.descriptor)};`, '  }', '');
      const verb = f.tag === 'select' ? 'select' : 'fill';
      lines.push(
        `  async ${name(methodName(verb, f.label))}(value: string): Promise<void> {`,
        `    await this.${getter}().${verb === 'select' ? 'selectOption' : 'fill'}(value);`,
        '  }',
        '',
      );
    }
    for (const t of ss.flatMap((s) => s.texts)) {
      if (getters.has(`text:${t.testid}`)) continue;
      const getter = name(`${camel(t.testid)}Text`);
      getters.set(`text:${t.testid}`, getter);
      lines.push(`  ${getter}(): Locator {`, `    return this.page.getByTestId(${q(t.testid)});`, '  }', '');
    }
    const open = route.includes('{id}')
      ? [`  async open(id: string): Promise<void> {`, `    await this.page.goto(${q(openPath)}.replace('{id}', encodeURIComponent(id)));`, '  }', '']
      : [`  async open(): Promise<void> {`, `    await this.page.goto(${q(openPath)});`, '  }', ''];
    const body = [
      "import type { Locator, Page } from '@playwright/test';",
      '',
      `/** ${route} — atomic UI actions only; assertions live in specs/. */`,
      `export class ${className} {`,
      '  constructor(private readonly page: Page) {}',
      '',
      ...open,
      ...lines,
    ];
    while (body[body.length - 1] === '') body.pop();
    body.push('}', '');
    const file = `pages/${className}.ts`;
    files.set(file, ts(body.join('\n')));
    pages.set(route, { route, className, file, openPath, getters });
  }
  return { files, pages };
}

function appConfigTs(inp: CompileInputs): string {
  const { config } = inp;
  const api = new URL(config.apiBaseUrl ?? config.baseUrl);
  const tenantEnv = new Map(config.tenants.map((t) => [t.id, t.codeEnv]));
  const b = inp.authScheme?.bearer;
  const auth =
    b?.source === 'localStorage'
      ? { kind: 'localStorage', key: b.key, header: b.header, prefix: b.prefix }
      : b?.source === 'cookie'
        ? { kind: 'cookie', names: b.names }
        : { kind: 'none' };
  const entities: Record<string, { createPath: string; teardown?: { method: string; path: string; actor?: string } }> = {};
  for (const bd of inp.bindings) {
    const plan = inp.teardownOps.get(bd.entity.name);
    const [method, path] = plan?.op.split(' ') ?? [];
    entities[bd.entity.name] = { createPath: bd.createPath, ...(method && path ? { teardown: { method, path, ...(plan?.actor ? { actor: plan.actor } : {}) } } : {}) };
  }
  const value = {
    id: config.id,
    baseUrl: config.baseUrl,
    apiOrigin: api.origin,
    apiSharesUiOrigin: api.origin === new URL(config.baseUrl).origin,
    loginPath: config.login.url,
    landingPath: config.login.successSignal?.startsWith('/') ? config.login.successSignal : '/',
    runTagPrefix: config.safety.runTagPrefix,
    auth,
    tenantHeader: inp.authScheme?.tenantHeader?.name ?? null,
    roles: config.roles.map((r) => ({ id: r.id, tenant: r.tenant, usernameEnv: r.usernameEnv, passwordEnv: r.passwordEnv, tenantCodeEnv: tenantEnv.get(r.tenant) ?? '' })),
    entities,
    implicitOracle: config.implicitOracle,
  };
  return ts(
    [
      'export interface RoleConfig {',
      '  id: string;',
      '  tenant: string;',
      '  usernameEnv: string;',
      '  passwordEnv: string;',
      '  tenantCodeEnv: string;',
      '}',
      'export type AuthConfig =',
      "  | { kind: 'localStorage'; key: string; header: string; prefix: string }",
      "  | { kind: 'cookie'; names: string[] }",
      "  | { kind: 'none' };",
      'export interface SuiteApp {',
      '  id: string;',
      '  baseUrl: string;',
      '  apiOrigin: string;',
      '  apiSharesUiOrigin: boolean;',
      '  loginPath: string;',
      '  landingPath: string;',
      '  runTagPrefix: string;',
      '  auth: AuthConfig;',
      '  tenantHeader: string | null;',
      '  roles: RoleConfig[];',
      '  entities: Record<string, { createPath: string; teardown?: { method: string; path: string; actor?: string } }>;',
      '  implicitOracle: { ignoreConsolePatterns: string[]; ignoreRequestPatterns: string[] };',
      '}',
      '',
      '/** Facts Pramaan observed about the app (auth scheme, roles, create/teardown operations). Credentials stay in env. */',
      `export const app: SuiteApp = ${JSON.stringify(value, null, 2)};`,
      '',
    ].join('\n'),
  );
}

/** Imports for a spec file, only what its bodies use (unused imports fail lint). */
function specImports(code: string, extra: string[] = []): string {
  const fx = ['test', 'expect', ...['call', 'jp', 'normalize'].filter((n) => new RegExp(`\\b${n}\\(`).test(code))];
  return [`import { ${fx.join(', ')} } from '../../fixtures';`, ...extra].join('\n');
}
const fixtureArgs = (code: string, candidates: string[]): string => {
  const used = candidates.filter((n) => new RegExp(`\\b${n}\\b`).test(code));
  return used.length > 0 ? `{ ${used.join(', ')} }` : '{}';
};

function assertionSpecs(inp: CompileInputs, index: TestIndexEntry[], skipped: Generated['skipped']): Map<string, string> {
  const files = new Map<string, string>();
  const createOps = new Map(inp.bindings.map((b) => [b.createOp, b.entity.name]));
  const groups = new Map<string, { title: string; body: string[]; tags: string[]; a: AssertionT; rule: RuleT; ops: string[]; reads: Record<string, string[]> }[]>();
  for (const a of inp.assertions.filter((x) => x.status === 'confirmed').sort((x, y) => x.id.localeCompare(y.id))) {
    const rule = inp.rules.find((r) => r.id === a.ruleId);
    if (!rule || rule.status !== 'confirmed') {
      skipped.push({ what: a.id, reason: `rule ${a.ruleId} is not confirmed` });
      continue;
    }
    try {
      const e = emitAssertion(a, createOps);
      const kind = e.actors.length >= 2 ? 'workflow' : 'api';
      const file = `specs/${kind}/${slug(rule.entities[0] ?? 'general', 4) || 'general'}.spec.ts`;
      const list = groups.get(file) ?? [];
      list.push({ title: testName(rule.title), body: e.body, tags: [kind === 'workflow' ? '@workflow' : '@api', '@regression'], a, rule, ops: e.operations, reads: e.reads });
      groups.set(file, list);
    } catch (err) {
      if (!(err instanceof CompileError)) throw err;
      skipped.push({ what: a.id, reason: err.message });
    }
  }
  for (const [file, tests] of [...groups.entries()].sort(([x], [y]) => x.localeCompare(y))) {
    const titles = uniqueNames(tests.map((t) => t.title));
    const blocks = tests.map((t, i) => {
      const code = t.body.join('\n');
      index.push({ file, title: titles[i] ?? t.title, tags: t.tags, oracle: 'confirmed-rule', operations: t.ops, reads: t.reads, ruleIds: [t.rule.id], assertionIds: [t.a.id] });
      return [
        `  // ${t.rule.id}: ${t.rule.title}`,
        `  test(${q(titles[i] ?? t.title)}, { tag: ${JSON.stringify(t.tags)} }, async (${fixtureArgs(code, ['api', 'steward', 'runTag', 'dates'])}) => {`,
        ...t.body.map((l) => (l === '' ? '' : `    ${l}`)),
        '  });',
      ].join('\n');
    });
    const all = blocks.join('\n\n');
    const entity = file.split('/').pop()?.replace('.spec.ts', '') ?? 'general';
    files.set(file, ts([specImports(all), '', `test.describe(${q(entity.replace(/_/g, ' '))}, () => {`, all, '});', ''].join('\n')));
  }
  return files;
}

function smokeSpec(inp: CompileInputs, pages: Map<string, PageInfo>, index: TestIndexEntry[]): string | undefined {
  const landing = inp.config.login.successSignal?.startsWith('/') ? inp.config.login.successSignal : undefined;
  const tests: string[] = [];
  const imports = new Set<string>();
  for (const role of inp.config.roles) {
    const st = inp.states.find((s) => s.role === role.id && (landing === undefined || s.route === landing)) ?? inp.states.find((s) => s.role === role.id);
    if (!st) continue;
    const page = pages.get(st.route);
    if (!page) continue;
    const nav = st.candidates.filter((c) => c.landmark && c.kind === 'link' && page.getters.has(c.key));
    if (nav.length === 0) continue;
    imports.add(page.className);
    const v = camel(page.className.replace(/Page$/, '')) || 'landing';
    const title = `should_show_main_navigation_when_${slug(role.id)}_logs_in`;
    index.push({ file: 'specs/ui/smoke.spec.ts', title, tags: ['@smoke'], oracle: 'implicit', operations: [`GET ${st.route}`], reads: {}, ruleIds: [], assertionIds: [] });
    tests.push(
      [
        `test(${q(title)}, { tag: ['@smoke'] }, async ({ pageAs }) => {`,
        '  // Arrange',
        `  const ${v} = new ${page.className}(await pageAs(${q(role.id)}));`,
        '',
        '  // Act',
        `  await ${v}.open();`,
        '',
        '  // Assert',
        ...nav.map((c) => `  await expect(${v}.${page.getters.get(c.key) ?? ''}(), ${q(`${role.id} should see the "${c.name}" navigation link`)}).toBeVisible();`),
        '});',
      ].join('\n'),
    );
  }
  if (tests.length === 0) return undefined;
  const imps = [...imports].sort().map((c) => `import { ${c} } from '../../pages/${c}';`);
  return ts([specImports(tests.join('\n'), imps), '', tests.join('\n\n'), ''].join('\n'));
}

/** UI element whose text equals a GET field for every role that saw both (value equality during the crawl). */
function consistencySpec(inp: CompileInputs, pages: Map<string, PageInfo>, index: TestIndexEntry[]): string | undefined {
  type Pair = { route: string; testid: string; op: string; path: string; field: string; roles: Set<string> };
  const pairs = new Map<string, Pair>();
  const rejected = new Set<string>();
  const primary = inp.config.tenants[0]?.id;
  const isPrimary = (role: string): boolean => inp.config.roles.find((r) => r.id === role)?.tenant === primary;
  for (const op of inp.model.operations.filter((o) => o.method === 'GET' && !o.path.includes('{') && o.query.length === 0)) {
    for (const s of inp.states) {
      if (!isPrimary(s.role)) continue;
      const obs = [...op.observations].reverse().find((o) => o.role === s.role && o.status === 200 && o.resBody !== null && typeof o.resBody === 'object' && !Array.isArray(o.resBody));
      if (!obs) continue;
      for (const t of s.texts) {
        for (const [field, value] of Object.entries(obs.resBody as Record<string, unknown>)) {
          if (typeof value !== 'number' && typeof value !== 'string') continue;
          const key = `${s.route}|${t.testid}|${op.key}|${field}`;
          if (String(value) !== t.text.trim()) {
            rejected.add(key);
            continue;
          }
          const p = pairs.get(key) ?? { route: s.route, testid: t.testid, op: op.key, path: op.path, field, roles: new Set<string>() };
          p.roles.add(s.role);
          pairs.set(key, p);
        }
      }
    }
  }
  // A text element must map to exactly one field (two fields with equal values for every role are ambiguous).
  const valid = [...pairs.entries()].filter(([k]) => !rejected.has(k)).map(([, p]) => p);
  const byElement = new Map<string, Pair[]>();
  for (const p of valid) byElement.set(`${p.route}|${p.testid}`, [...(byElement.get(`${p.route}|${p.testid}`) ?? []), p]);
  const chosen = [...byElement.values()].filter((ps) => ps.length === 1).map((ps) => ps[0] as Pair);
  if (chosen.length === 0) return undefined;

  const binding = inp.bindings.find((b) => b.approve);
  const tests: string[] = [];
  const imports = new Set<string>();
  for (const p of chosen.sort((a, b) => `${a.route}${a.testid}`.localeCompare(`${b.route}${b.testid}`))) {
    const page = pages.get(p.route);
    const getter = page?.getters.get(`text:${p.testid}`);
    if (!page || !getter) continue;
    imports.add(page.className);
    for (const role of [...p.roles].sort()) {
      const v = camel(page.className.replace(/Page$/, '')) || 'view';
      // A state change the UI must reflect: the role's own request, approved by someone else.
      const approver = binding?.approve && binding.approve.actor !== role ? binding.approve.actor : undefined;
      const mutate = binding && approver
        ? [
            `  const created = await steward.create(${q(binding.entity.name)}, { actor: ${q(role)}, body: ${bodyLiteral(binding, 90 + tests.length * 2)} });`,
            `  const approved = await call(await api.as(${q(approver)}), 'POST', ${q(binding.approve?.path ?? '')}.replace('{id}', String(created.id)));`,
            `  expect(approved.status, ${q(`${approver} should approve the request that changes what the screen shows`)}).toBe(${binding.approve?.status ?? 200});`,
          ]
        : [];
      const title = `should_show_the_api_${slug(p.field)}_when_${slug(role)}_reloads_${slug(p.route) || 'home'}`;
      index.push({ file: 'specs/ui/consistency.spec.ts', title, tags: ['@regression'], oracle: 'consistency', operations: [p.op, `GET ${p.route}`, ...(binding && approver ? [binding.createOp, binding.approve?.op ?? ''] : [])], reads: { [p.op]: [`$.${p.field}`] }, ruleIds: [], assertionIds: [] });
      tests.push(
        [
          `test(${q(title)}, { tag: ['@regression'] }, async ({ ${['pageAs', 'api', ...(mutate.length > 0 ? ['steward', 'runTag', 'dates'] : [])].join(', ')} }) => {`,
          '  // Arrange',
          `  const ${v} = new ${page.className}(await pageAs(${q(role)}));`,
          `  await ${v}.open();`,
          ...mutate,
          '',
          '  // Act',
          `  await ${v}.open();`,
          `  const fromApi = await call(await api.as(${q(role)}), 'GET', ${q(p.path)});`,
          '',
          '  // Assert',
          `  await expectUiMatchesApi(${v}.${getter}(), jp(fromApi.body, ${q(`$.${p.field}`)}), 'number', ${q(`${p.testid} on ${p.route} should show the API's ${p.field}`)});`,
          '});',
        ].join('\n'),
      );
    }
  }
  if (tests.length === 0) return undefined;
  const code = tests.join('\n\n');
  const imps = [...[...imports].sort().map((c) => `import { ${c} } from '../../pages/${c}';`), "import { expectUiMatchesApi } from '../../helpers/consistency';"];
  return ts([specImports(code, imps), '', code, ''].join('\n'));
}

/** A create body literal from the crawl recipe with this run's tag and an own date window (TS source). */
function bodyLiteral(b: Binding, offset: number): string {
  const entries = Object.entries(b.recipe).map(([k, v]) => {
    let expr = JSON.stringify(v);
    if (k === b.freeTextField) expr = '`${runTag} consistency`';
    else if (k === b.fromField || k === b.toField) expr = `dates.todayPlus(${offset})`;
    else if (k === b.daysField) expr = '1';
    else if (k === b.halfDayField) expr = 'false';
    return `${/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k)}: ${expr}`;
  });
  return `{ ${entries.join(', ')} }`;
}

function authzFiles(inp: CompileInputs, index: TestIndexEntry[], skipped: Generated['skipped']): Map<string, string> {
  const files = new Map<string, string>();
  const rows: unknown[] = [];
  let offset = 120;
  for (const r of inp.matrix.rows.filter((x) => x.status === 'confirmed').sort((a, b) => a.operation.localeCompare(b.operation))) {
    const [method = 'GET', pathAndQuery = ''] = r.operation.split(' ');
    const [path = '', qKeys] = pathAndQuery.split('?');
    const record = path.includes('{id}');
    const mutating = method !== 'GET';
    const cells = Object.entries(r.expected)
      .filter(([actor, e]) => e !== 'unknown' && r.observed[actor]?.outcome !== 'skipped')
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([actor, expect]) => ({ actor, expect }));
    if (cells.length === 0) continue;
    // Query values: from the owner's first successful call with exactly these keys.
    const op = inp.model.operations.find((o) => o.key === `${method} ${path}`);
    const keys = qKeys ? qKeys.split('&') : [];
    const sample = op?.observations.find((o) => o.role === r.ownerRole && o.status >= 200 && o.status < 300 && o.query.join('&') === keys.join('&'));
    const query = sample ? Object.fromEntries([...new URL(sample.url).searchParams.entries()].sort()) : {};
    let target: Record<string, unknown> = {};
    if (record || mutating) {
      const entity = inp.entities.find((e) => e.operations.includes(`${method} ${path}`));
      const b = inp.bindings.find((x) => x.entity.name === entity?.name);
      if (!entity || !b) {
        skipped.push({ what: `authz ${r.operation}`, reason: 'no create operation to prepare an owned record' });
        continue;
      }
      // Drive the fresh record to the state where the owner's call was legal.
      const sm = entity.stateMachine;
      const from = sm?.transitions.find((t) => t.op === `${method} ${path}` && t.observed)?.from;
      const drive: { method: string; path: string; actor: string }[] = [];
      if (mutating && sm && from !== undefined) {
        let cur = sm.initial.includes(from) ? from : undefined;
        if (cur === undefined) {
          const t = sm.transitions.find((x) => x.observed && x.to === from && sm.initial.includes(x.from));
          if (t) {
            const [m = 'POST', p = ''] = t.op.split(' ');
            drive.push({ method: m, path: p, actor: t.actors.find((a) => a !== 'anonymous') ?? b.creator });
            cur = from;
          }
        }
        if (cur === undefined) {
          skipped.push({ what: `authz ${r.operation}`, reason: `cannot reach state ${from}` });
          continue;
        }
      }
      const createBody = Object.fromEntries(
        Object.entries(b.recipe).map(([k, v]) => [
          k,
          k === b.freeTextField ? '{{runTag}} authz' : k === b.fromField || k === b.toField ? `{{today+${offset}}}` : k === b.daysField ? 1 : v,
        ]),
      );
      offset += 2;
      target = { entity: entity.name, creator: record && !mutating ? r.ownerRole : b.creator, createBody, drive };
    }
    const rowSlug = slug(`${method} ${path} ${keys.join(' ')}`.replace(/[{}]/g, ''), 16);
    rows.push({ slug: rowSlug, operation: r.operation, method, path, query, ownerRole: r.ownerRole, record, mutating, ...target, cells });
    for (const c of cells) {
      const required = slug(SATISFIES[c.expect as keyof typeof SATISFIES].join(' or '));
      index.push({ file: 'specs/authz/authz-matrix.spec.ts', title: `should_return_${required}_for_${slug(c.actor)}_when_calling_${rowSlug}`, tags: ['@authz', '@regression'], oracle: 'authz-matrix', operations: [`${method} ${path}`], reads: { [`${method} ${path}`]: [mutating ? '#status' : '$'] }, ruleIds: [], assertionIds: [] });
    }
  }
  if (rows.length === 0) return files;
  files.set(
    'specs/authz/authz-matrix.data.ts',
    ts(
      [
        "import type { AuthzRow } from '../../helpers/authz-target';",
        '',
        '/** Confirmed role-matrix rows (spec/role-matrix.yaml). Cells with expectation "unknown" are never emitted. */',
        `export const matrix: AuthzRow[] = ${JSON.stringify(rows, null, 2)};`,
        '',
      ].join('\n'),
    ),
  );
  files.set(
    'specs/authz/authz-matrix.spec.ts',
    ts(
      [
        "import { test, expect, call } from '../../fixtures';",
        "import { classify, SATISFIES } from '../../helpers/authz';",
        "import { prepareTarget } from '../../helpers/authz-target';",
        "import { matrix } from './authz-matrix.data';",
        '',
        "const slug = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');",
        '',
        'for (const row of matrix) {',
        '  for (const cell of row.cells) {',
        "    const required = SATISFIES[cell.expect];",
        "    test(`should_return_${slug(required.join(' or '))}_for_${slug(cell.actor)}_when_calling_${row.slug}`, { tag: ['@authz', '@regression'] }, async ({ api, steward, runTag, dates }) => {",
        '      // Arrange',
        '      const target = await prepareTarget(row, { api, steward, runTag, dates });',
        '',
        '      // Act',
        '      const res = await call(await api.as(cell.actor), row.method, target.path, { params: row.query });',
        '',
        '      // Assert',
        '      const outcome = classify(res, target.baseline, { mutating: row.mutating, collection: !row.record });',
        "      expect(required, `${cell.actor} calling ${row.operation} on ${row.ownerRole}'s data should be ${required.join(' or ')} (matrix: ${cell.expect}; HTTP ${res.status})`).toContain(outcome);",
        '    });',
        '  }',
        '}',
        '',
      ].join('\n'),
    ),
  );
  return files;
}

export const AUTHZ_TARGET_TS = `import { call, type Api } from './api';
import type { Expectation } from './authz';
import type { dates as Dates } from './dates';
import type { Steward } from './steward';

export interface AuthzRow {
  slug: string;
  operation: string;
  method: string;
  path: string;
  query: Record<string, string>;
  ownerRole: string;
  record: boolean;
  mutating: boolean;
  entity?: string;
  creator?: string;
  createBody?: Record<string, unknown>;
  drive?: { method: string; path: string; actor: string }[];
  cells: { actor: string; expect: Expectation }[];
}

function fill(v: unknown, runTag: string, dates: typeof Dates): unknown {
  if (typeof v === 'string') {
    const day = /^\\{\\{today\\+(\\d+)\\}\\}$/.exec(v);
    if (day) return dates.todayPlus(Number(day[1]));
    return v.replace('{{runTag}}', runTag);
  }
  if (Array.isArray(v)) return v.map((x) => fill(x, runTag, dates));
  if (v !== null && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, fill(x, runTag, dates)]));
  return v;
}

/** The owner's record (created by this test, driven to the right state) and the owner's own view of it. */
export async function prepareTarget(
  row: AuthzRow,
  ctx: { api: Api; steward: Steward; runTag: string; dates: typeof Dates },
): Promise<{ path: string; baseline: unknown }> {
  let path = row.path;
  if (row.entity && row.creator) {
    const created = await ctx.steward.create(row.entity, { actor: row.creator, body: fill(row.createBody ?? {}, ctx.runTag, ctx.dates) });
    if (created.id === undefined) throw new Error(\`could not create a \${row.entity} as \${row.creator} (HTTP \${created.status})\`);
    path = row.path.replace('{id}', encodeURIComponent(created.id));
    for (const step of row.drive ?? []) {
      const res = await call(await ctx.api.as(step.actor), step.method, step.path.replace('{id}', encodeURIComponent(created.id)));
      if (res.status < 200 || res.status >= 300) throw new Error(\`could not drive \${row.entity} via \${step.method} \${step.path} as \${step.actor} (HTTP \${res.status})\`);
    }
  }
  if (row.mutating) return { path, baseline: undefined };
  const own = await call(await ctx.api.as(row.ownerRole), row.method, path, { params: row.query });
  return { path, baseline: own.body };
}
`;

function pramaanMd(inp: CompileInputs, index: TestIndexEntry[], skipped: Generated['skipped']): string {
  const by = (o: string): number => index.filter((t) => t.oracle === o).length;
  const covered = new Set(index.flatMap((t) => t.operations));
  const ops = inp.model.operations.map((o) => o.key);
  const confirmedRules = inp.rules.filter((r) => r.status === 'confirmed');
  return [
    `# ${inp.config.name} — QA suite`,
    '',
    'Generated by [Pramaan](https://github.com/Rapaka-balu/Pramaan) from what it observed in the app and what the QA lead confirmed.',
    'It is plain Playwright + TypeScript and runs **without Pramaan and without any LLM**.',
    '',
    '## Run it',
    '',
    '```bash',
    'npm ci',
    'npx playwright install chromium',
    'cp .env.example .env   # fill in the test logins',
    'npx playwright test                    # everything',
    'npx playwright test --grep @smoke      # fast check on every push',
    'npx playwright test --grep @regression # nightly',
    '```',
    '',
    '## Coverage',
    '',
    '| What | Count |',
    '| --- | --- |',
    `| Tests from confirmed business rules (\`@api\`, \`@workflow\`) | ${by('confirmed-rule')} |`,
    `| Authorization matrix tests (\`@authz\`) | ${by('authz-matrix')} |`,
    `| UI ↔ API consistency tests | ${by('consistency')} |`,
    `| Smoke tests (one per role) | ${by('implicit')} |`,
    `| Observed API operations exercised | ${ops.filter((o) => covered.has(o)).length} / ${ops.length} |`,
    `| Confirmed rules with an assertion | ${confirmedRules.filter((r) => r.assertionIds.length > 0).length} / ${confirmedRules.length} |`,
    `| Confirmed role-matrix rows | ${inp.matrix.rows.filter((r) => r.status === 'confirmed').length} / ${inp.matrix.rows.length} |`,
    '',
    ...(skipped.length > 0 ? ['## Not compiled', '', ...skipped.map((s) => `- \`${s.what}\`: ${s.reason}`), ''] : []),
    '## Layout',
    '',
    '`pages/` atomic UI actions · `flows/` journeys · `specs/` assertions only · `fixtures/` sessions, API clients, data steward,',
    'implicit oracle · `helpers/` reusable checks · `config/` environment · `spec/` the Living Spec this suite was compiled from.',
    '',
    'Every test creates its own data tagged `PRM-<runId>-…` and tears it down. Edit tests through `spec/` and recompile;',
    'files without the `generated by pramaan` header are yours and are never overwritten.',
    '',
  ].join('\n');
}

function envExample(inp: CompileInputs): string {
  const names = new Set<string>();
  for (const t of inp.config.tenants) names.add(t.codeEnv);
  for (const r of inp.config.roles) {
    names.add(r.usernameEnv);
    names.add(r.passwordEnv);
  }
  return ['# Where the app runs', `BASE_URL=${inp.config.baseUrl}`, 'API_ORIGIN=', '', '# Test logins (never commit real values)', ...[...names].map((n) => `${n}=`), ''].join('\n');
}

export function generateSuite(inp: CompileInputs): Generated {
  const files = new Map<string, string>();
  const index: TestIndexEntry[] = [];
  const skipped: Generated['skipped'] = [];
  const { files: pageFiles, pages } = buildPages(inp.states, inp.config.login.url);

  files.set('package.json', S.packageJson(inp.config.id));
  files.set('tsconfig.json', S.TSCONFIG);
  files.set('.gitignore', S.GITIGNORE);
  files.set('eslint.config.mjs', S.ESLINT_CONFIG);
  files.set('eslint-rules/pramaan.mjs', S.ESLINT_PLUGIN);
  files.set('playwright.config.ts', ts(S.PLAYWRIGHT_CONFIG));
  files.set('config/env.ts', ts(S.ENV_TS));
  files.set('config/app.ts', appConfigTs(inp));
  files.set('helpers/api.ts', ts(S.API_TS));
  files.set('helpers/steward.ts', ts(S.STEWARD_TS));
  files.set('helpers/run-ledger.ts', ts(S.RUN_LEDGER_TS));
  files.set('helpers/faults.ts', ts(FAULTS_TS));
  files.set('fixtures/global-teardown.ts', ts(S.GLOBAL_TEARDOWN_TS));
  files.set('helpers/dates.ts', ts(S.DATES_TS));
  files.set('helpers/normalize.ts', ts(S.NORMALIZE_TS));
  files.set('helpers/consistency.ts', ts(S.CONSISTENCY_TS));
  files.set('helpers/authz.ts', ts(S.AUTHZ_TS));
  files.set('helpers/authz-target.ts', ts(AUTHZ_TARGET_TS));
  files.set('helpers/jsonpath.ts', ts(`${inp.jsonpathSource.replace(/^\/\/.*\n/, '// JSONPath subset copied from Pramaan (no eval).\n')}\n/** Value at a JSONPath, or undefined. */\nexport const jp = (value: unknown, path: string): unknown => evaluateJsonPath(path, value);\n`));
  files.set('flows/login.ts', ts(S.LOGIN_FLOW_TS));
  files.set('flows/registry.ts', ts(S.FLOW_REGISTRY_TS));
  files.set('fixtures/index.ts', ts(S.FIXTURES_TS));
  files.set('fixtures/global-setup.ts', ts(S.GLOBAL_SETUP_TS));
  for (const [p, c] of pageFiles) files.set(p, c);

  const smoke = smokeSpec(inp, pages, index);
  if (smoke) files.set('specs/ui/smoke.spec.ts', smoke);
  for (const [p, c] of assertionSpecs(inp, index, skipped)) files.set(p, c);
  for (const [p, c] of authzFiles(inp, index, skipped)) files.set(p, c);
  const consistency = consistencySpec(inp, pages, index);
  if (consistency) files.set('specs/ui/consistency.spec.ts', consistency);

  for (const [name, text] of Object.entries(inp.specTexts)) files.set(`spec/${name}`, text);
  for (const a of inp.assertions) files.set(`spec/assertions/${a.id}.json`, `${JSON.stringify(a, null, 2)}\n`);
  index.sort((a, b) => `${a.file}|${a.title}`.localeCompare(`${b.file}|${b.title}`));
  files.set('spec/test-index.json', `${JSON.stringify({ tests: index }, null, 2)}\n`);
  const mirrored = inp.ledgerEvents.filter((e) => MIRRORED.has(e.type) && !(e.type === 'run.completed' && e.data['command'] === 'compile'));
  files.set('spec/decisions.jsonl', mirrored.map((e) => JSON.stringify(e)).join('\n') + (mirrored.length > 0 ? '\n' : ''));

  const secrets = [...new Set([...inp.config.tenants.map((t) => t.codeEnv), ...inp.config.roles.flatMap((r) => [r.usernameEnv, r.passwordEnv])])];
  files.set('.github/workflows/qa.yml', S.qaWorkflow(secrets));
  files.set('.env.example', envExample(inp));
  files.set('PRAMAAN.md', pramaanMd(inp, index, skipped));
  return { files, index, skipped };
}


